@@ -0,0 +1,94 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { mkdtempSync, writeFileSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { openStore } from "../src/db/store.js";
+import { createApp } from "../src/http/server.js";
+import { t } from "../src/i18n/messages.js";
+import { app, auth, NOW, seed } from "./helpers.js";
+
+test("missing or unknown key is 401 in the error shape", async () => {
+  const { handle } = app();
+  for (const headers of [undefined, {}, { Authorization: "Basic abc" }, { Authorization: "Bearer nope" }]) {
+    const res = await handle({ path: "/items", headers });
+    assert.equal(res.status, 401);
+    assert.equal(res.body.error.code, "unauthorized");
+    assert.ok(res.body.error.message);
+  }
+  assert.notEqual(t("unauthorized", "ko"), t("unauthorized", "en"));
+  assert.notEqual(t("forbidden", "ko"), t("forbidden", "en"));
+});
+
+test("viewer may read GET routes except /audit, and may not write", async () => {
+  const { handle } = app();
+  const headers = { Authorization: "Bearer viewer-key" };
+  assert.equal((await handle({ path: "/items", headers })).status, 200);
+  const audit = await handle({ path: "/audit", headers });
+  assert.equal(audit.status, 403);
+  assert.equal(audit.body.error.code, "forbidden");
+  for (const [method, path, body] of [
+    ["POST", "/recipes/1/cook", { portions: 4 }],
+    ["POST", "/batches/1/waste", { qty: 1 }],
+    ["POST", "/temperatures", { location: "fridge", celsius: 3 }],
+    ["POST", "/orders", { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] }],
+    ["PUT", "/items/1/allergens", { allergens: ["milk"] }],
+  ]) {
+    const res = await handle({ method, path, headers, body });
+    assert.equal(res.status, 403);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("cook may cook, waste, log temperatures and enter stocktake counts only", async () => {
+  const { handle } = app();
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: auth(), body: { location: "dry" } })).body;
+
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: auth("cook-key"), body: { portions: 4 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: auth("cook-key"), body: { qty: 0.5, reason: "spoil" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: auth("cook-key"), body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: auth("cook-key"), body: { batchId: 6, counted: 12 } })).status, 200);
+
+  for (const [method, path, body] of [
+    ["GET", "/audit", null],
+    ["POST", "/stocktakes", { location: "fridge" }],
+    ["POST", `/stocktakes/${take.id}/finish`, null],
+    ["POST", "/orders", { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] }],
+    ["PUT", "/items/1/allergens", { allergens: ["milk"] }],
+    ["POST", "/prices", { supplierId: 1, itemId: 1, priceCents: 190, validFrom: "2026-10-28" }],
+    ["POST", "/dishes", { name: "Toast", recipeId: 1, priceCents: 500 }],
+    ["POST", "/jobs/nightly", null],
+  ]) {
+    const res = await handle({ method, path, headers: auth("cook-key"), body });
+    assert.equal(res.status, 403, `${method} ${path} should be 403`);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("audit records data-changing requests newest first and persists on save", async () => {
+  let clock = NOW;
+  const dir = mkdtempSync(join(tmpdir(), "larder-audit-"));
+  const file = join(dir, "db.json");
+  writeFileSync(file, JSON.stringify(seed()));
+  const handle = createApp(openStore(file), { clock: () => clock });
+
+  await handle({ path: "/items", headers: auth("viewer-key") });
+  await handle({ method: "POST", path: "/recipes/2/cook", headers: auth("cook-key"), body: { portions: 100 } });
+  await handle({ method: "POST", path: "/recipes/1/cook", headers: auth("cook-key"), body: { portions: 4 } });
+  clock += 1000;
+  await handle({ method: "POST", path: "/orders", headers: auth("manager-key"), body: { supplierId: 1, lines: [{ itemId: 1, qty: 2 }] } });
+
+  const reopened = createApp(openStore(file), { clock: () => clock });
+  const res = await reopened({ path: "/audit", headers: auth("manager-key") });
+  assert.equal(res.status, 200);
+  assert.equal(res.body.length, 2);
+  assert.deepEqual(
+    res.body.map(({ keyName, method, path, status }) => ({ keyName, method, path, status })),
+    [
+      { keyName: "Manager", method: "POST", path: "/orders", status: 201 },
+      { keyName: "Cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+    ],
+  );
+  assert.equal(res.body[0].at, new Date(NOW + 1000).toISOString());
+  assert.equal(res.body[1].at, new Date(NOW).toISOString());
+});
